22	static std::string GetFP8Type(DataType type) {
23	  std::stringstream stream;
24	  int32_t lanes = type.lanes();
25	  std::string vec;
26	  if (type.is_scalar()) {
27	    vec = "";
28	  } else if (lanes == 2) {
29	    vec = "_2";
30	  } else if (lanes == 4) {
31	    vec = "_4";
32	  } else if (lanes == 8) {
33	    vec = "_8";
34	  } else if (lanes == 16) {
35	    vec = "_16";
36	  } else {
37	    LOG(FATAL) << "Only support scalar and vector types of width (2, 4, 8, 16) "
38	                  "for FP8";
39	  }
40	  if (type.code() == DataType::kFloat8_e4m3fn) {
41	    stream << "fp8_e4" << vec << "_t";
42	  } else if (type.code() == DataType::kFloat8_e4m3fnuz) {
43	    stream << "fp8_e4" << vec << "_t";
44	  } else if (type.code() == DataType::kFloat8_e4m3) {
45	    stream << "fp8_e4" << vec << "_t";
46	  } else if (type.code() == DataType::kFloat8_e4m3b11fnuz) {
47	    stream << "fp8_e4" << vec << "_t";
48	  } else if (type.code() == DataType::kFloat8_e5m2) {
49	    stream << "fp8_e5" << vec << "_t";
50	  } else if (type.code() == DataType::kFloat8_e5m2fnuz) {
51	    stream << "fp8_e5" << vec << "_t";
52	  } else if (type.code() == DataType::kFloat8_e8m0fnu) {
53	    stream << "fp8_e8" << vec << "_t";
54	  } else {
55	    LOG(FATAL) << "Unsupported FP8 type in HIP codegen: " << type;
56	  }
57	  return stream.str();
58	}
