60	/*!
61	 * \brief Replace patterns with replacement strings.
62	 * \note should use std::format instead when codebase is ported to C++20.
63	 */
64	class Replacer {
65	public:
66	  void register_rule(const std::string &pattern,
67	                     const std::string &replacement) {
68	    _rules.emplace_back(pattern, replacement);
69	  }
70	  std::string rewrite(std::string str) {
71	    for (auto &&rule : _rules) {
72	      auto [pattern, replacement] = rule;
73	      size_t len = pattern.size();
74	      size_t new_len = replacement.size();
75	      size_t pos = str.find(pattern);
76	      while (pos != std::string::npos) {
77	        str = str.replace(pos, len, replacement);
78	        pos = str.find(pattern, pos + new_len);
79	      }
80	    }
81	    return str;
82	  }
83	  void empty_rules() { _rules.clear(); }
84	
85	private:
86	  std::vector<std::pair<std::string, std::string>> _rules;
87	};
