95	class LaunchConfigExtractor : public tir::StmtVisitor {
96	private:
97	  void VisitStmt_(const AttrStmtNode *op) final {
98	    if (op->attr_key == tir::attr::thread_extent) {
99	      IterVar iv = Downcast<IterVar>(op->node);
100	      if (iv->var->name_hint == "threadIdx.x" ||
101	          iv->thread_tag == "threadIdx.x") {
102	        threadIdx_x_ext = op->value;
103	      } else if (iv->var->name_hint == "threadIdx.y" ||
104	                 iv->thread_tag == "threadIdx.y") {
105	        threadIdx_y_ext = op->value;
106	      } else if (iv->var->name_hint == "threadIdx.z" ||
107	                 iv->thread_tag == "threadIdx.z") {
108	        threadIdx_z_ext = op->value;
109	      }
110	    }
111	    StmtVisitor::VisitStmt_(op);
112	  }
113	
114	public:
115	  PrimExpr threadIdx_x_ext = Integer(1);
116	  PrimExpr threadIdx_y_ext = Integer(1);
117	  PrimExpr threadIdx_z_ext = Integer(1);
118	};
