120	void CodeGenTileLangHIP::PrintExtraAttrs(const PrimFunc &f, std::ostream &os) {
121	  LaunchConfigExtractor extractor;
122	  extractor(f->body);
123	  arith::Analyzer analyzer;
124	  PrimExpr threadIdx_ext =
125	      analyzer.Simplify(extractor.threadIdx_x_ext * extractor.threadIdx_y_ext *
126	                        extractor.threadIdx_z_ext);
127	  if (const IntImmNode *const threadIdx_ext_int =
128	          threadIdx_ext.as<IntImmNode>()) {
129	    if (threadIdx_ext_int->value == 1) {
130	      // unable to extract the number of threads per block, hence directly
131	      // return
132	      return;
133	    }
134	    stream << " __launch_bounds__(" << threadIdx_ext_int->value << ")";
135	  }
136	}
