159	void CodeGenTileLangHIP::VisitStmt_(const tir::ForNode *op) {
160	  if (op->kind == tir::ForKind::kUnrolled) {
161	    PrintIndent();
162	    stream << "#pragma unroll\n";
163	  }
164	  std::string extent =
165	      PrintExpr(arith::Analyzer().Simplify(op->extent + op->min));
166	  PrintIndent();
167	  std::string vid = AllocVarID(op->loop_var.get());
168	  std::string start = PrintExpr(op->min);
169	  stream << "for (";
170	  PrintType(op->loop_var.dtype(), stream);
171	  stream << ' ' << vid << " = " << start << "; " << vid << " < " << extent
172	         << "; ++" << vid << ") {\n";
173	  int for_scope = BeginScope();
174	  PrintStmt(op->body);
175	  this->EndScope(for_scope);
176	  PrintIndent();
177	  stream << "}\n";
178	}
