186	void CodeGenTileLangHIP::PrintType(DataType t, std::ostream &os) { // NOLINT(*)
187	  int lanes = t.lanes();
188	  if (t.is_handle()) {
189	    ICHECK(t.is_scalar()) << "do not yet support vector types";
190	    os << "void*";
191	    return;
192	  }
193	
194	  if (t.is_void()) {
195	    os << "void";
196	    return;
197	  }
198	
199	  if (t == tl::cuTensorMapType()) {
200	    os << "CUtensorMap";
201	    return;
202	  }
203	
204	  bool fail = false;
205	  if (t.is_float()) {
206	    switch (t.bits()) {
207	    case 16:
208	      if (t.is_scalar()) {
209	        os << "half_t";
210	      } else if (lanes <= 8) {
211	        // Emit CUDA code to access fp16 vector elements.
212	        //
213	        // half4 is stored as uint2
214	        //
215	        // h4.x is emitted as *(half2*)(&(u2.x)).x
216	        // h4.y is emitted as *(half2*)(&(u2.x)).y
217	        // h4.z is emitted as *(half2*)(&(u2.y)).x
218	        // h4.w is emitted as *(half2*)(&(u2.y)).y
219	        //
220	        ICHECK_EQ(lanes % 2, 0) << "only support even lane for half type";
221	        os << "uint" << lanes / 2;
222	      } else {
223	        fail = true;
224	      }
225	      break;
226	    case 32:
227	      if (lanes <= 4) {
228	        os << "float";
229	      } else if (lanes <= 8) {
230	        // Emit CUDA code to access fp32 vector elements for 4 < lanes <= 8.
231	        //
232	        // float8 is stored as ulonglong4
233	        //
234	        // f8.v1 is emitted as *(float2*)(&(ul4.x)).x
235	        // f8.v2 is emitted as *(float2*)(&(ul4.x)).y
236	        //
237	        ICHECK_EQ(lanes % 2, 0)
238	            << "only support even lane for float type with lanes > 4";
239	        os << "ulonglong" << lanes / 2;
240	      } else {
241	        fail = true;
242	      }
243	      break;
244	    case 64:
245	      os << "double";
246	      break;
247	    default:
248	      fail = true;
249	      break;
250	    }
251	    if (!fail && (t.is_scalar() || t.bits() == 16))
252	      return;
253	    if (!fail && (lanes > 4 && lanes <= 8 && t.bits() == 32))
254	      return;
255	    if (!fail && (lanes >= 2 && lanes <= 4)) {
256	      os << lanes;
257	      return;
258	    }
259	  } else if (t.is_bfloat16()) {
260	    if (t.is_scalar()) {
261	      os << "bfloat16_t";
262	    } else if (lanes <= 8) {
263	      ICHECK_EQ(lanes % 2, 0) << "only support even lane for half type";
264	      os << "uint" << lanes / 2;
265	    } else {
266	      fail = true;
267	    }
268	    if (!fail)
269	      return;
270	  } else if (t.is_float8()) {
271	    enable_fp8_ = true;
272	    os << GetFP8Type(t);
273	    return;
274	  } else if (t == DataType::Bool()) {
275	    os << "bool";
276	    return;
277	  } else if (t.is_vector_bool()) {
278	    // CUDA does not support bool vectors.
279	    // Use ushort vectors to represent instead.
280	    int n = t.lanes();
281	    if (n <= 4) {
282	      os << "ushort" << n;
283	      return;
284	    }
285	  } else if (t.is_uint() || t.is_int()) {
286	    if (t.is_uint()) {
287	      os << "u";
288	    }
289	    switch (t.bits()) {
290	    case 1: {
291	      if (t.is_scalar()) {
292	        os << "int";
293	        return;
294	      } else if (t.lanes() == 8) {
295	        os << "int8_t";
296	        return;
297	      } else if (t.lanes() == 16) {
298	        os << "int16_t";
299	        return;
300	      } else if (t.lanes() == 32) {
301	        os << "int";
302	        return;
303	      } else {
304	        LOG(FATAL) << "Cannot convert type " << t << " to CUDA type!";
305	      }
306	    }
307	    case 4: {
308	      if (t.is_scalar()) {
309	        os << "int";
310	        return;
311	      } else if (t.lanes() == 4) {
312	        os << "int16_t";
313	        return;
314	      } else if (t.lanes() == 8) {
315	        // directly 8 4-bit int in integer.
316	        os << "int";
317	        return;
318	      } else if (t.lanes() == 16) {
319	        os << "int2";
320	        return;
321	      } else if (t.lanes() == 32) {
322	        os << "int4";
323	        return;
324	      } else if (t.lanes() == 64) {
325	        os << "int8";
326	        return;
327	      } else {
328	        LOG(FATAL) << "Cannot convert type " << t << " to CUDA type!";
329	      }
330	    }
331	    case 8: {
332	      if (t.lanes() == 4) {
333	        // directly 4 8 bit int in integer.
334	
335	        // We use int for int8x4 instead of char4 because using char4 is
336	        // likely to produce extra instructions to pack four int8 elements
337	        // into 32-bit data.
338	        os << "int";
339	        return;
340	      } else if (t.lanes() == 8) {
341	        os << "int2";
342	        return;
343	      } else if (t.lanes() == 16) {
344	        os << "int4";
345	        return;
346	      } else if (!t.is_uint() && t.is_scalar()) {
347	        os << "signed char";
348	        break;
349	      } else {
350	        os << "char";
351	        break;
352	      }
353	    }
354	    case 16: {
355	      if (t.is_scalar()) {
356	        os << "short";
357	      } else if (t.lanes() <= 4) {
358	        os << "short" << lanes;
359	      } else if (t.lanes() <= 8) {
360	        // Emit CUDA code to access int16 vector elements.
361	        //
362	        // short4 is stored as int2
363	        //
364	        // s4.x is emitted as *(short2*)(&(i2.x)).x
365	        // s4.y is emitted as *(short2*)(&(i2.x)).y
366	        // s4.z is emitted as *(short2*)(&(i2.y)).x
367	        // s4.w is emitted as *(short2*)(&(i2.y)).y
368	        //
369	        ICHECK_EQ(t.lanes() % 2, 0)
370	            << "only support even lane for shorT type with lanes > 4";
371	        os << "int" << t.lanes() / 2;
372	      } else {
373	        fail = true;
374	      }
375	      if (!fail) {
376	        return;
377	      }
378	      break;
379	    }
380	    case 32: {
381	      if (t.is_scalar()) {
382	        os << "int";
383	      } else if (t.lanes() <= 4) {
384	        os << "int" << t.lanes();
385	      } else if (t.lanes() <= 8) {
386	        // Emit CUDA code to access int32 vector elements for 4 < lanes <= 8.
387	        //
388	        // int8 is stored as longlong4
389	        //
390	        // i8.v1 is emitted as *(int2*)(&(l4.x)).x
391	        // i8.v2 is emitted as *(int2*)(&(l4.x)).y
392	        //
393	        ICHECK_EQ(lanes % 2, 0)
394	            << "only support even lane for int32 type with lanes > 4";
395	        os << "longlong" << lanes / 2;
396	      } else {
397	        fail = true;
398	      }
399	      if (!fail) {
400	        return;
401	      }
402	      break;
403	    }
404	    case 64: {
405	      if (t.is_scalar()) {
406	        os << "int64_t";
407	      } else if (t.lanes() == 2) {
408	        os << "longlong2";
409	      } else if (t.lanes() == 3) {
410	        os << "longlong3";
411	      } else if (t.lanes() == 4) {
412	        os << "longlong4";
413	      }
414	      return;
415	    }
416	    default:
417	      fail = true;
418	      break;
419	    }
420	    if (!fail && lanes == 1) {
421	      return;
422	    }
423	    if (!fail && (lanes >= 2 && lanes <= 4)) {
424	      os << lanes;
425	      return;
426	    }
427	  }
428	  LOG(FATAL) << "Cannot convert type " << t << " to CUDA type";
429	}
