431	void CodeGenTileLangHIP::PrintVecBinaryOp(const std::string &op, DataType t,
432	                                          PrimExpr lhs, PrimExpr rhs,
433	                                          std::ostream &os) { // NOLINT(*)
434	  // Declare the result.
435	  std::string sret = name_supply_->FreshName("_");
436	  this->PrintIndent();
437	  this->PrintType(t, stream);
438	  stream << ' ' << sret << ";\n";
439	  int ssa_scope = BeginScope();
440	  {
441	    // Unpack into individual ops.
442	    std::string vlhs = SSAGetID(PrintExpr(lhs), lhs.dtype());
443	    std::string vrhs = SSAGetID(PrintExpr(rhs), rhs.dtype());
444	
445	    for (int i = 0, lanes = t.lanes(); i < lanes; ++i) {
446	      std::ostringstream value_temp;
447	      if (isalpha(op[0])) {
448	        value_temp << op << "(";
449	        PrintVecElemLoad(vlhs, lhs.dtype(), i, value_temp);
450	        value_temp << ", ";
451	        PrintVecElemLoad(vrhs, rhs.dtype(), i, value_temp);
452	        value_temp << ")";
453	      } else {
454	        value_temp << "(";
455	        PrintVecElemLoad(vlhs, lhs.dtype(), i, value_temp);
456	        value_temp << op;
457	        PrintVecElemLoad(vrhs, rhs.dtype(), i, value_temp);
458	        value_temp << ")";
459	      }
460	      PrintVecElemStore(sret, t, i, value_temp.str());
461	    }
462	  }
463	  EndScope(ssa_scope);
464	  os << sret;
465	}
466	
467	void CodeGenTileLangHIP::PrintVecElemLoad(const std::string &vec, DataType t,
468	                                          int i,
469	                                          std::ostream &os) { // NOLINT(*)
470	  if (t.is_scalar()) {
471	    os << vec;
472	    return;
473	  }
474	
475	  static const char access[] = {'x', 'y', 'z', 'w'};
476	  ICHECK(i >= 0 && i < (t.bits() == 8                        ? 16
477	                        : (t.bits() == 16 || t.bits() == 32) ? 8
478	                                                             : 4));
479	  if (t.bits() == 8 && (t.is_int() || t.is_uint())) {
480	    std::string type_name = t.is_int() ? "char" : "unsigned char";
481	    if (t.lanes() == 2 || t.lanes() == 3) {
482	      os << vec << "." << access[i % t.lanes()];
483	    } else {
484	      std::string ac = t.lanes() == 4 ? vec : (vec + "." + access[i / 4]);
485	      os << "((" << type_name << ")(" << ac << " >> " << i % 4 * 8 << "))";
486	    }
487	  } else if (t.is_float16()) {
488	    os << "((half2*)(&(" << vec << "." << access[i / 2] << ")))->"
489	       << access[i % 2];
490	  } else if (t.is_bfloat16()) {
491	    os << "((bfloat16x2*)(&(" << vec << "." << access[i / 2] << ")))->"
492	       << access[i % 2];
493	  } else if (t.lanes() > 4 && t.lanes() <= 8) {
494	    std::string type_name;
495	    if (t.bits() == 16) {
496	      if (t.is_int()) {
497	        type_name = "short";
498	      } else if (t.is_uint()) {
499	        type_name = "ushort";
500	      }
501	    } else if (t.bits() == 32) {
502	      if (t.is_int()) {
503	        type_name = "int";
504	      } else if (t.is_uint()) {
505	        type_name = "uint";
506	      } else if (t.is_float()) {
507	        type_name = "float";
508	      }
509	    }
510	    ICHECK(!type_name.empty());
511	    os << "((" << type_name << "2*)(&(" << vec << "." << access[i / 2]
512	       << ")))->" << access[i % 2];
513	  } else {
514	    os << vec << "." << access[i];
515	  }
516	}
517	
518	void CodeGenTileLangHIP::PrintVecElemStore(const std::string &vec, DataType t,
519	                                           int i, const std::string &value) {
520	  this->PrintIndent();
521	  static const char access[] = {'x', 'y', 'z', 'w'};
522	  ICHECK(i >= 0 && i < (t.bits() == 8                        ? 16
523	                        : (t.bits() == 16 || t.bits() == 32) ? 8
524	                                                             : 4));
525	  if (t.bits() == 8 && (t.is_int() || t.is_uint())) {
526	    if (t.lanes() == 2 || t.lanes() == 3) {
527	      stream << vec << '.' << access[i % t.lanes()] << "="
528	             << "(" << value << ");\n";
529	    } else {
530	      std::string ac = t.lanes() == 4 ? vec : (vec + "." + access[i / 4]);
531	      stream << ac << "=";
532	      // Do not read the first undef lane.
533	      if (i != 0) {
534	        stream << ac << " & ~(0x000000ff << " << i % 4 * 8 << ") |";
535	      }
536	      stream << "(" << value << " << " << i % 4 * 8 << ");\n";
537	    }
538	  } else if (t.is_float16()) {
539	    stream << "*((half_t*)(&(((half2*)(&(" << vec << "." << access[i / 2]
540	           << ")))->" << access[i % 2] << "))) = " << value << ";\n";
541	  } else if (t.is_bfloat16()) {
542	    stream << "((bfloat16_t*)(&(" << vec << "." << access[i / 2] << ")))["
543	           << (i % 2) << "] = " << value << ";\n";
544	  } else if (t.lanes() > 4 && t.lanes() <= 8) {
545	    std::string type_name;
546	    if (t.bits() == 16) {
547	      if (t.is_int()) {
548	        type_name = "short";
549	      } else if (t.is_uint()) {
550	        type_name = "ushort";
551	      }
552	    } else if (t.bits() == 32) {
553	      if (t.is_int()) {
554	        type_name = "int";
555	      } else if (t.is_uint()) {
556	        type_name = "uint";
557	      } else if (t.is_float()) {
558	        type_name = "float";
559	      }
560	    }
561	    ICHECK(!type_name.empty());
562	    stream << "((" << type_name << "2*)(&(" << vec << "." << access[i / 2]
563	           << ")))->" << access[i % 2] << " = " << value << ";\n";
564	  } else {
565	    stream << vec << "." << access[i] << " = " << value << ";\n";
566	  }
567	}
