591	std::string CodeGenTileLangHIP::CastFromTo(std::string value, DataType from,
592	                                           DataType target) {
593	  if (from == target)
594	    return value;
595	  std::ostringstream os;
596	  os << "((";
597	  this->PrintType(target, os);
598	  os << ")";
599	  if (from.is_float16() && (target.is_int() || target.is_uint()) &&
600	      target.bits() == 8) {
601	    os << "(";
602	    if (target.is_uint()) {
603	      os << "u";
604	    }
605	    os << "int)";
606	  }
607	  os << value << ")";
608	  return os.str();
609	}
610	
611	void CodeGenTileLangHIP::VisitExpr_(const CastNode *op, std::ostream &os) {
612	  DataType from_ty = op->value.dtype();
613	  DataType target_ty = op->dtype;
614	  ICHECK_EQ(target_ty.lanes(), from_ty.lanes());
615	
616	  // Emit simple C-style type conversion.
617	  if (from_ty.is_scalar())
618	    return CodeGenC::VisitExpr_(op, os);
619	
620	  // We could emit make_float4 like calls, but the emitted code looks
621	  // too compact to read. Emit this as vectorized unary ops.
622	  std::string sret = name_supply_->FreshName("_");
623	  this->PrintIndent();
624	  this->PrintType(target_ty, stream);
625	  stream << ' ' << sret << ";\n";
626	  {
627	    std::string src = SSAGetID(PrintExpr(op->value), from_ty);
628	    for (int i = 0, lanes = from_ty.lanes(); i < lanes; ++i) {
629	      std::ostringstream val;
630	      val << "(";
631	      PrintType(target_ty.element_of(), val);
632	      val << ")(";
633	      PrintVecElemLoad(src, from_ty, i, val);
634	      val << ")";
635	      PrintVecElemStore(sret, target_ty, i, val.str());
636	    }
637	  }
638	  os << sret;
639	}
