641	void CodeGenTileLangHIP::PrintCallExtern(Type ret_type, String global_symbol,
642	                                         const Array<PrimExpr> &args,
643	                                         bool skip_first_arg,
644	                                         std::ostream &os) { // NOLINT(*)
645	  DataType ret_dtype = GetRuntimeDataType(ret_type);
646	  if (ret_dtype.is_vector()) {
647	    //
648	    // Emit an unsupported vector call
649	    //
650	    // v = intrin_f((float4*)A[0], (float4*)B[0])
651	    //
652	    // as
653	    //
654	    // float4 __ret;
655	    // {
656	    //   float4 __arg0 = ((float4*)A)[0];
657	    //   float4 __arg1 = ((float4*)B)[0];
658	    //   __ret.x = intrin_f(__arg0.x, __arg1.x);
659	    //   __ret.y = intrin_f(__arg0.y, __arg1.y);
660	    //   __ret.z = intrin_f(__arg0.z, __arg1.z);
661	    //   __ret.w = intrin_f(__arg0.w, __arg1.w);
662	    // }
663	    // v = __ret;
664	    //
665	    // Declare the result vector.
666	    std::string sret = name_supply_->FreshName("_");
667	    this->PrintIndent();
668	    this->PrintType(ret_dtype, stream);
669	    stream << ' ' << sret << ";\n";
670	    {
671	      // Load arguments.
672	      std::vector<std::string> sargs;
673	      size_t arg_begin = static_cast<size_t>(skip_first_arg);
674	      for (size_t i = arg_begin; i < args.size(); ++i) {
675	        std::string val = SSAGetID(PrintExpr(args[i]), args[i].dtype());
676	        sargs.push_back(std::move(val));
677	      }
678	
679	      // Emit a scalar call for each lane.
680	      for (int i = 0; i < ret_dtype.lanes(); ++i) {
681	        std::ostringstream scall;
682	        scall << global_symbol << "(";
683	        for (size_t j = 0; j < sargs.size(); ++j) {
684	          if (j > 0)
685	            scall << ", ";
686	          PrintVecElemLoad(sargs[j], args[arg_begin + j].dtype(), i, scall);
687	        }
688	        scall << ")";
689	        PrintVecElemStore(sret, ret_dtype, i, scall.str());
690	      }
691	    }
692	    os << sret;
693	  } else {
694	    CodeGenC::PrintCallExtern(ret_type, global_symbol, args, skip_first_arg,
695	                              os);
696	  }
697	}
