699	// Print a reference expression to a buffer.
700	std::string CodeGenTileLangHIP::GetBufferRef(DataType t,
701	                                             const BufferNode *buffer,
702	                                             PrimExpr index) {
703	  const VarNode *buffer_var = buffer->data.get();
704	  std::ostringstream os;
705	  std::string vid = GetVarID(buffer_var);
706	  std::string scope;
707	  if (alloc_storage_scope_.count(buffer_var)) {
708	    scope = alloc_storage_scope_.at(buffer_var);
709	  }
710	  // bool is_vol = IsVolatile(buffer_var);
711	  // always false for tl cutlass backend.
712	  bool is_vol = false;
713	
714	  auto ptr_cast = [this, is_vol, scope](DataType pointed_to) {
715	    std::ostringstream ptr_os;
716	    ptr_os << "(";
717	    if (is_vol) {
718	      ptr_os << "volatile ";
719	    }
720	    if (!scope.empty() && IsScopePartOfType()) {
721	      PrintStorageScope(scope, ptr_os);
722	    }
723	    PrintType(pointed_to, ptr_os);
724	    ptr_os << "*)";
725	    return ptr_os.str();
726	  };
727	
728	  DataType buffer_element_dtype = buffer->dtype;
729	
730	  std::string buffer_str = vid;
731	  if (!HandleTypeMatch(buffer_var, buffer_element_dtype) || is_vol) {
732	    std::stringstream temp;
733	    temp << "(" << ptr_cast(buffer_element_dtype) << vid << ")";
734	    buffer_str = temp.str();
735	  }
736	
737	  std::string index_str = PrintExpr(index);
738	  if (t.bits() == 4 || (t.bits() == 1 && t.is_int())) {
739	    // This is a special case, because CodegenCUDA::PrintType()
740	    // returns "int" for bool and for 4-bit integers. In most cases,
741	    // we divide by the number of lanes to determine the index.
742	    // However, the backing type for scalar int4 and scalar bool is
743	    // int32.  Therefore, we need to divide by the ratio of their
744	    // sizes in that case.
745	    int div_factor = (t.lanes() == 1) ? (32 / t.bits()) : t.lanes();
746	
747	    os << "*("
748	       << "(" << ptr_cast(t) << vid << ")"
749	       << " + " << index_str << " / " << div_factor << ")";
750	  } else if (t == buffer_element_dtype) {
751	    os << buffer_str << "[" << index_str << "]";
752	  } else {
753	    os << "*" << ptr_cast(t) << "(" << buffer_str << " + " << index_str << ")";
754	  }
755	
756	  return os.str();
757	}
758	
759	void CodeGenTileLangHIP::VisitExpr_(const CallNode *op, std::ostream &os) {
760	  auto print_extern_call_stmt = [&](std::string name, size_t offset = 0) {
761	    this->PrintIndent();
762	    this->stream << name << "(";
763	    for (size_t i = offset; i < op->args.size(); i++) {
764	      if (i > offset)
765	        this->stream << ", ";
766	      this->stream << this->PrintExpr(op->args[i]);
767	    }
768	    this->stream << ");\n";
769	  };
770	  if (op->op.same_as(builtin::ptx_cp_async())) {
771	    std::string dst = this->PrintExpr(op->args[0]);
772	    std::string dst_offset = this->PrintExpr(op->args[1]);
773	    std::string src = this->PrintExpr(op->args[2]);
774	    std::string src_offset = this->PrintExpr(op->args[3]);
775	    std::string size = this->PrintExpr(op->args[4]);
776	    // use size of argument list to indicate whether or not to use predicated
777	    // cp.async
778	    if (op->args.size() == 5) {
779	      this->PrintIndent();
780	      this->stream << "tl::cp_async_gs<" << size << ">(" << dst << "+"
781	                   << dst_offset << ", " << src << "+" << src_offset << ");\n";
782	    } else {
783	      std::string condition = this->PrintExpr(op->args[5]);
784	      this->PrintIndent();
785	      this->stream << "tl::cp_async_gs_conditional<" << size << ">(" << dst
786	                   << "+" << dst_offset << ", " << src << "+" << src_offset
787	                   << ", " << condition << ");\n";
788	    }
789	  } else if (op->op.same_as(builtin::ptx_commit_group())) {
790	    print_extern_call_stmt("tl::cp_async_commit");
791	  } else if (op->op.same_as(builtin::ptx_wait_group())) {
792	    int n = Downcast<IntImm>(op->args[0])->value;
793	    std::string func_name = "tl::cp_async_wait<" + std::to_string(n) + ">";
794	    print_extern_call_stmt(func_name, 1);
795	  } else if (op->op.same_as(builtin::create_barriers())) {
796	    this->PrintIndent();
797	    int barrier_count = Downcast<IntImm>(op->args[0])->value;
798	    std::string barrier_name = "_mbarrier";
799	    this->stream << "__shared__ uint64_t " << barrier_name << "["
800	                 << barrier_count << "];\n";
801	  } else if (op->op.same_as(tl::get_mbarrier())) {
802	    std::string barrier_name = "_mbarrier";
803	    std::string barrier_id = this->PrintExpr(op->args[0]);
804	    os << barrier_name + "[" + barrier_id + "]";
805	  } else if (op->op.same_as(builtin::ptx_arrive_barrier())) {
806	    print_extern_call_stmt("tl::mbarrier_arrive");
807	  } else if (op->op.same_as(builtin::ptx_init_barrier_thread_count())) {
808	    print_extern_call_stmt("tl::mbarrier_init");
809	  } else if (op->op.same_as(builtin::ptx_arrive_barrier_expect_tx())) {
810	    print_extern_call_stmt("tl::mbarrier_arrive_expect_tx");
811	  } else if (op->op.same_as(builtin::ptx_cp_async_barrier())) {
812	    print_extern_call_stmt("tl::mbarrier_cp_async_arrive");
813	  } else if (op->op.same_as(tl::mbarrier_expect_tx())) {
814	    print_extern_call_stmt("tl::mbarrier_expect_tx");
815	  } else if (op->op.same_as(tl::mbarrier_wait_parity())) {
816	    print_extern_call_stmt("tl::mbarrier_wait");
817	  } else if (op->op.same_as(tl::ptx_stmatrix())) {
818	    int trans = Downcast<IntImm>(op->args[0])->value;
819	    int num = Downcast<IntImm>(op->args[1])->value;
820	    std::string func_name = "tl::ptx_stmatrix_x" + std::to_string(num);
821	    if (trans == 1)
822	      func_name += "_trans";
823	    print_extern_call_stmt(func_name, 2);
824	  } else if (op->op.same_as(tl::wait_wgmma())) {
825	    this->PrintIndent();
826	    int num_mma = Downcast<IntImm>(op->args[0])->value;
827	    this->stream << "tl::wait_wgmma<" << std::to_string(num_mma) << ">();\n";
828	  } else if (op->op.same_as(tl::pack_b16())) {
829	    os << "__pack_half2(" << this->PrintExpr(op->args[0]) << ", "
830	       << this->PrintExpr(op->args[1]) << ")";
831	  } else if (op->op.same_as(tl::__ldg())) {
832	    // HIP fallback: regular load
833	    const BufferLoadNode *bl = op->args[0].as<BufferLoadNode>();
834	    ICHECK(bl) << "T.__ldg expects a BufferLoad as the first argument.";
835	    ICHECK_EQ(bl->indices.size(), 1)
836	        << "T.__ldg currently supports flattened 1D buffer accesses.";
837	    const BufferNode *buffer = bl->buffer.get();
838	    PrimExpr base = bl->indices[0];
839	    auto buffer_ref = this->GetBufferRef(op->dtype, buffer, base);
840	    os << buffer_ref;
841	  } else if (op->op.same_as(builtin::tvm_fill_fragment())) {
842	    need_mma_h_ = true;
843	    ICHECK_EQ(op->args.size(), 6U);
844	    os << "nvcuda::wmma::fill_fragment(";
845	    this->PrintExpr(op->args[0], os);
846	    os << "[";
847	    this->PrintExpr(op->args[4], os);
848	    os << "], ";
849	    this->PrintExpr(op->args[5], os);
850	    os << ")";
851	  } else if (op->op.same_as(builtin::tvm_load_matrix_sync())) {
852	    need_mma_h_ = true;
853	    ICHECK_EQ(op->args.size(), 8U);
854	    os << "nvcuda::wmma::load_matrix_sync(";
855	    this->PrintExpr(op->args[0], os);
856	    os << "[";
857	    this->PrintExpr(op->args[4], os);
858	    os << "], ";
859	    this->PrintExpr(op->args[5], os);
860	    os << ", ";
861	    this->PrintExpr(op->args[6], os);
862	    os << ")";
863	  } else if (op->op.same_as(builtin::tvm_store_matrix_sync())) {
864	    need_mma_h_ = true;
865	    ICHECK_EQ(op->args.size(), 8U);
866	    os << "nvcuda::wmma::store_matrix_sync(";
867	    this->PrintExpr(op->args[5], os);
868	    os << ", ";
869	    this->PrintExpr(op->args[0], os);
870	    os << "[";
871	    this->PrintExpr(op->args[4], os);
872	    os << "], ";
873	    this->PrintExpr(op->args[6], os);
874	    if (const StringImmNode *str = op->args[7].as<StringImmNode>()) {
875	      os << ", nvcuda::wmma::mem_" << str->value;
876	    } else {
877	      LOG(FATAL) << "Invalid parameters";
878	    }
879	    os << ")";
880	  } else if (op->op.same_as(builtin::tvm_mma_sync())) {
881	    need_mma_h_ = true;
882	    ICHECK_EQ(op->args.size(), 8U);
883	    os << "nvcuda::wmma::mma_sync(";
884	    for (int i = 0; i < 4; ++i) {
885	      this->PrintExpr(op->args[i * 2], os);
886	      os << "[";
887	      this->PrintExpr(op->args[i * 2 + 1], os);
888	      os << "]" << ((i < 3) ? ", " : ")");
889	    }
890	  } else if (op->op.same_as(builtin::tvm_bmma_sync())) {
891	    need_mma_h_ = true;
892	    ICHECK_EQ(op->args.size(), 8U);
893	    os << "nvcuda::wmma::bmma_sync(";
894	    for (int i = 0; i < 4; ++i) {
895	      this->PrintExpr(op->args[i * 2], os);
896	      os << "[";
897	      this->PrintExpr(op->args[i * 2 + 1], os);
898	      os << "]" << ((i < 3) ? ", " : ")");
899	    }
900	  } else if (op->op.same_as(tl::tvm_mfma())) {
901	    // arg 0: prefix: {otype}_{intrM}x{intrN}x{intrK}_{itype}
902	    // arg 1: A layout: row/col
903	    // arg 2: B layout: row/col
904	    // arg 3: A precision: float16, float32, ...
905	    // arg 4: B precision: float16, float32, ...
906	    // arg 5: C precision: float32, float64, ...
907	    // arg 6: A multiplicand
908	    // arg 7: A multiplicand index
909	    // arg 8: B multiplicand
910	    // arg 9: B multiplicand index
911	    // arg 10: C accumulator
912	    // arg 11: C accumulator index
913	
914	    ICHECK(op->args.size() == 12U)
915	        << "Invalid number of arguments for tvm_mfma";
916	    std::string prefix = Downcast<StringImm>(op->args[0])->value;
917	    std::string A_layout = Downcast<StringImm>(op->args[1])->value;
918	    std::string B_layout = Downcast<StringImm>(op->args[2])->value;
919	    std::string A_dtype = Downcast<StringImm>(op->args[3])->value;
920	    std::string B_dtype = Downcast<StringImm>(op->args[4])->value;
921	    std::string C_dtype = Downcast<StringImm>(op->args[5])->value;
922	    std::string a_ref = this->PrintExpr(op->args[6]);
923	    std::string a_bias = this->PrintExpr(op->args[7]);
924	    std::string b_ref = this->PrintExpr(op->args[8]);
925	    std::string b_bias = this->PrintExpr(op->args[9]);
926	    std::string c_ref = this->PrintExpr(op->args[10]);
927	    std::string c_bias = this->PrintExpr(op->args[11]);
928	    ICHECK(A_layout == "row" || B_layout == "row")
929	        << "Matrix core only support row major";
930	    // map for dtype -> float32x4 -> float4
931	    std::unordered_map<std::string, std::string> dtype_map = {
932	        {"int8", "char"},
933	        {"int32", "int"},
934	        {"int8x4", "int32_t"},
935	        {"int8x8", "int64_t"},
936	        {"int32x4", "int32x4"},
937	        {"float16", "half"},
938	        {"float32", "float"},
939	        {"float64", "double"},
940	        {"float16x4", "float16x4"},
941	        {"bfloat16x4", "bfloat16x4_vec"},
942	        {"float32x4", "float32x4"},
943	        {"float8_e4m3fnuzx4", "fp8_e4_4_t"},
944	        {"float8_e4m3fnuzx8", "long"},
945	        {"float32x16", "float32x16"}};
946	    std::string call_mfma_code = R"({
947	      *((({C_dtype}*){c_ref}) + {c_bias}) = {mfma_buildin}(*((({A_dtype}*){a_ref}) + {a_bias}),
948	                    *((({B_dtype}*){b_ref}) + {b_bias}),
949	                    *((({C_dtype}*){c_ref}) + {c_bias}), 0, 0, 0);
950	    })";
951	    std::string mfma_buildin = "__builtin_amdgcn_mfma_" + prefix;
952	    Replacer replacer;
953	
954	    replacer.register_rule("{mfma_buildin}", mfma_buildin);
955	    replacer.register_rule("{A_dtype}", dtype_map[A_dtype]);
956	    replacer.register_rule("{B_dtype}", dtype_map[B_dtype]);
957	    replacer.register_rule("{C_dtype}", dtype_map[C_dtype]);
958	    replacer.register_rule("{a_ref}", a_ref);
959	    replacer.register_rule("{a_bias}", a_bias);
960	    replacer.register_rule("{b_ref}", b_ref);
961	    replacer.register_rule("{b_bias}", b_bias);
962	    replacer.register_rule("{c_ref}", c_ref);
963	    replacer.register_rule("{c_bias}", c_bias);
964	    os << replacer.rewrite(call_mfma_code);
965	  } else if (op->op.same_as(builtin::thread_return())) {
966	    os << "return";
967	  } else if (op->op.same_as(tl::tl_gemm())) {
968	    ICHECK(op->args.size() == 4) << "tl_gemm expects 4 arguments <op_instance, "
969	                                    "A_ptr, B_ptr, C_ptr>, but got "
970	                                 << op->args.size();
971	    auto op_instance = Downcast<StringImm>(op->args[0]);
972	    this->PrintCallExtern(GetType(tvm::ffi::GetRef<PrimExpr>(op)),
973	                          op_instance->value, op->args, true, os);
974	  } else if (op->op.same_as(tl::tl_gemm_sp())) {
975	    LOG(FATAL) << "tl_gemm_sp is not supported on HIP";
976	  } else if (op->op.same_as(tl::loop_break())) {
977	    this->PrintIndent();
978	    this->stream << "break;\n";
979	  } else if (op->op.same_as(tl::no_set_max_nreg())) {
980	    // HIP doesn't need explicit register management like CUDA
981	    // This is a no-op for HIP
982	    return;
983	  } else {
984	    CodeGenC::VisitExpr_(op, os);
985	  }
986	}
