988	void CodeGenTileLangHIP::VisitStmt_(const AttrStmtNode *op) {
989	  if (op->attr_key == tir::attr::async_commit_queue_scope) {
990	    const IntImmNode *queue_id = op->value.as<IntImmNode>();
991	    ICHECK(queue_id && queue_id->value == 0)
992	        << "For CUDA, the index of an async queue must be 0.";
993	    this->VisitStmt(op->body);
994	    auto commit_group = Call(DataType::Void(), builtin::ptx_commit_group(), {});
995	    this->VisitExpr(commit_group, this->stream);
996	    return;
997	  } else if (op->attr_key == tir::attr::async_wait_queue_scope) {
998	    auto wait_attrs = GetAsyncWaitAttributes(op);
999	    auto queue_id = wait_attrs.first.as<IntImmNode>();
1000	    ICHECK(queue_id && queue_id->value == 0)
1001	        << "For CUDA, the index of an async queue must be 0.";
1002	    auto wait_cnt = wait_attrs.second;
1003	    auto wait_group =
1004	        Call(DataType::Void(), builtin::ptx_wait_group(), {wait_cnt});
1005	    this->VisitExpr(wait_group, this->stream);
1006	    auto inner = op->body.as<AttrStmtNode>();
1007	    ICHECK(inner);
1008	    this->VisitStmt(inner->body);
1009	    return;
1010	  } else if (op->attr_key == "threadblock_swizzle_pattern") {
1011	    this->PrintIndent();
1012	    const StringImmNode *pattern = op->value.as<StringImmNode>();
1013	    ICHECK(pattern);
1014	    this->stream << "const dim3 blockIdx = " << pattern->value << "();\n";
1015	    this->VisitStmt(op->body);
1016	    return;
1017	  }
1018	  CodeGenC::VisitStmt_(op);
1019	}
