1021	void CodeGenTileLangHIP::VisitStmt_(const AllocateNode *op) {
1022	  ICHECK(!is_zero(op->condition));
1023	  std::string vid = AllocVarID(op->buffer_var.get());
1024	
1025	  this->PrintIndent();
1026	  std::string scope = GetPtrStorageScope(op->buffer_var);
1027	  PrintStorageScope(scope, stream);
1028	  PrintType(op->dtype, stream);
1029	
1030	  if (scope == "shared.dyn") {
1031	    stream << ' ' << vid << "[];\n";
1032	  } else {
1033	    size_t constant_size = op->ConstantAllocationSize();
1034	    ICHECK_GT(constant_size, 0)
1035	        << "Can only handle constant size stack allocation for now";
1036	
1037	    if ((op->dtype == DataType::Int(4) || op->dtype == DataType::UInt(4) ||
1038	         op->dtype == DataType::Int(1)) &&
1039	        scope == "shared") {
1040	      constant_size = constant_size / (32 / op->dtype.bits());
1041	    }
1042	    stream << ' ' << vid << '[' << constant_size << "];\n";
1043	  }
1044	
1045	  RegisterHandleType(op->buffer_var.get(), op->dtype);
1046	  this->PrintStmt(op->body);
1047	}
