1049	void CodeGenTileLangHIP::VisitExpr_(const RampNode *op, std::ostream &os) {
1050	  int lanes = static_cast<int>(Downcast<IntImm>(op->lanes)->value);
1051	  CHECK_LE(lanes, 4) << "ValueError: Ramp of more than 4 lanes is not allowed.";
1052	  os << "(make_";
1053	  PrintType(op->dtype, os);
1054	  os << "(";
1055	  for (int i = 0; i < lanes; i++) {
1056	    os << "(" << PrintExpr(op->base) << ")"
1057	       << "+(" << PrintExpr(op->stride) << "*" << i << ")";
1058	    if (i != lanes - 1)
1059	      os << ", ";
1060	  }
1061	  os << "))";
1062	}
1063	
1064	void CodeGenTileLangHIP::VisitExpr_(const BroadcastNode *op,
1065	                                    std::ostream &os) { // NOLINT(*)
1066	  int lanes = static_cast<int>(Downcast<IntImm>(op->lanes)->value);
1067	  if ((op->dtype.is_int() || op->dtype.is_uint()) && op->dtype.bits() == 8 &&
1068	      lanes == 4) {
1069	    // make_int8x4
1070	    const int64_t *p = as_const_int(op->value);
1071	    ICHECK(p);
1072	    int64_t v = *p & 0xFF;
1073	    v = (v << 24) | (v << 16) | (v << 8) | v;
1074	    if (op->dtype.is_uint()) {
1075	      os << "(uint)" << v;
1076	    } else {
1077	      os << "(int)" << v;
1078	    }
1079	    return;
1080	  }
1081	
1082	  if (op->dtype.is_float16()) {
1083	    std::string v = PrintExpr(op->value);
1084	    os << "make_";
1085	    PrintType(op->dtype, os);
1086	    os << '(';
1087	    for (int i = 0; i < lanes / 2; ++i) {
1088	      if (i != 0)
1089	        os << ", ";
1090	      os << "__pack_half2(" << v << ", " << v << ")";
1091	    }
1092	    os << ')';
1093	    return;
1094	  }
1095	
1096	  if (op->dtype.is_bfloat16()) {
1097	    std::string v = PrintExpr(op->value);
1098	    os << "make_";
1099	    PrintType(op->dtype, os);
1100	    os << '(';
1101	    for (int i = 0; i < lanes / 2; ++i) {
1102	      if (i != 0)
1103	        os << ", ";
1104	      os << "__pack_bfloat162(" << v << ", " << v << ")";
1105	    }
1106	    os << ')';
1107	    return;
1108	  }
1109	
1110	  if (op->dtype.is_float() && op->dtype.bits() == 32 &&
1111	      op->dtype.lanes() == 8) {
1112	    std::string v = PrintExpr(op->value);
1113	    os << "make_ulonglong4(";
1114	    for (int i = 0; i < 4; ++i) {
1115	      if (i != 0)
1116	        os << ", ";
1117	      os << "*(unsigned long long*)&make_float2(" << v << ", " << v << ")";
1118	    }
1119	    os << ')';
1120	    return;
1121	  }
1122	
1123	  if ((op->dtype.is_int() || op->dtype.is_uint()) && op->dtype.bits() == 4) {
1124	    bool fail = false;
1125	    const int64_t *p = as_const_int(op->value);
1126	    ICHECK(p);
1127	    int64_t v = *p & 0xF;
1128	
1129	    if (lanes == 4) {
1130	      v = (v << 12) | (v << 8) | (v << 4) | v;
1131	      if (op->dtype.is_uint()) {
1132	        os << "(uint16_t)" << v;
1133	      } else {
1134	        os << "(int16_t)" << v;
1135	      }
1136	    } else {
1137	      v = (v << 28) | (v << 24) | (v << 20) | (v << 16) | (v << 12) | (v << 8) |
1138	          (v << 4) | v;
1139	      if (lanes == 8) {
1140	        if (op->dtype.is_uint()) {
1141	          os << "(uint)" << v;
1142	        } else {
1143	          os << "(int)" << v;
1144	        }
1145	      } else if (lanes == 16 || lanes == 32) {
1146	        os << "make_";
1147	        PrintType(op->dtype, os);
1148	        os << '(';
1149	        for (int i = 0; i < lanes / 8; ++i) {
1150	          if (i != 0)
1151	            os << ", ";
1152	          if (op->dtype.is_uint()) {
1153	            os << "(uint)" << v;
1154	          } else {
1155	            os << "(int)" << v;
1156	          }
1157	        }
1158	        os << ')';
1159	      } else {
1160	        fail = true;
1161	      }
1162	    }
1163	
1164	    if (!fail) {
1165	      return;
1166	    }
1167	  }
1168	
1169	  std::string v = PrintExpr(op->value);
1170	  os << "make_";
1171	  PrintType(op->dtype, os);
1172	  os << '(';
1173	  for (int i = 0; i < lanes; ++i) {
1174	    if (i != 0)
1175	      os << ", ";
1176	    os << v;
1177	  }
1178	  os << ')';
1179	}
