1181	inline void PrintConst(const FloatImmNode *op, std::ostream &os,
1182	                       CodeGenTileLangHIP *p) { // NOLINT(*)
1183	  // Type code is kBFloat
1184	  if (op->dtype.is_bfloat16()) {
1185	    os << "bfloat16_t";
1186	    os << '(' << std::scientific << op->value << 'f' << ')';
1187	    return;
1188	  } else if (op->dtype.is_float8_e4m3fnuz() || op->dtype.is_float8_e4m3() ||
1189	             op->dtype.is_float8_e4m3fn()) {
1190	    os << "fp8_e4_t";
1191	    os << '(' << std::scientific << op->value << 'f' << ')';
1192	    return;
1193	  }
1194	  // Type code is kFloat
1195	  switch (op->dtype.bits()) {
1196	  case 64:
1197	  case 32: {
1198	    std::ostringstream temp;
1199	    if (std::isinf(op->value)) {
1200	      if (op->value < 0) {
1201	        temp << "-";
1202	      }
1203	      temp << ((op->dtype.bits() == 32) ? "HUGE_VALF" : "HUGE_VAL");
1204	    } else if (std::isnan(op->value)) {
1205	      temp << ((op->dtype.bits() == 32) ? "NAN" : "NAN");
1206	    } else {
1207	      temp << std::scientific << op->value;
1208	      if (op->dtype.bits() == 32)
1209	        temp << 'f';
1210	    }
1211	    p->MarkConst(temp.str());
1212	    os << temp.str();
1213	    break;
1214	  }
1215	  case 16: {
1216	    os << "half_t" << '(';
1217	    FloatImm const_f32 = FloatImm(DataType::Float(32), op->value);
1218	    PrintConst(const_f32.get(), os, p);
1219	    os << ')';
1220	    break;
1221	  }
1222	  default:
1223	    LOG(FATAL) << "Bad bit-width for float: " << op->dtype << "\n";
1224	  }
1225	}
1226	
1227	void CodeGenTileLangHIP::VisitExpr_(const FloatImmNode *op,
1228	                                    std::ostream &os) { // NOLINT(*)
1229	  PrintConst(op, os, this);
1230	}
