1232	void CodeGenTileLangHIP::HandleVolatileLoads(const std::string &value,
1233	                                             const BufferLoadNode *op,
1234	                                             std::ostream &os) {
1235	  // Cast away volatile qualifier for fp16 types. That is, only loads and
1236	  // stores are volatile. The loaded objects are not marked as volatile.
1237	  //
1238	  if ((op->dtype.is_float16() || op->dtype.is_bfloat16()) &&
1239	      IsVolatile(op->buffer->data.get())) {
1240	    os << "(";
1241	    PrintType(op->dtype, os);
1242	    os << ")(" << value << ")";
1243	  } else {
1244	    os << value;
1245	  }
1246	}
