1248	void CodeGenTileLangHIP::PrintVecElemLoadExpr(DataType t, int i,
1249	                                              const std::string &value,
1250	                                              std::ostream &os) {
1251	  ICHECK_GT(t.lanes(), 1);
1252	  if (t.bits() == 8 && (t.is_int() || t.is_uint())) {
1253	    if (!(t.lanes() == 2 || t.lanes() == 3)) {
1254	      if (i != 0) {
1255	        os << "|";
1256	      }
1257	      os << "((0x000000ff << " << i * 8 << ") & (" << value << " << " << i * 8
1258	         << "))";
1259	      return;
1260	    }
1261	  }
1262	
1263	  if (t.is_float16()) {
1264	    if (i == 0) {
1265	      os << "make_";
1266	      PrintType(t, os);
1267	      os << '(';
1268	    }
1269	    if (i % 2 == 0) {
1270	      os << "__pack_half2(" << value;
1271	    } else {
1272	      os << "," << value << ")";
1273	      if (i != t.lanes() - 1) {
1274	        os << ",";
1275	      } else {
1276	        os << ")";
1277	      }
1278	    }
1279	    return;
1280	  }
1281	
1282	  if (t.is_bfloat16()) {
1283	    if (i == 0) {
1284	      os << "make_";
1285	      PrintType(t, os);
1286	      os << '(';
1287	    }
1288	    if (i % 2 == 0) {
1289	      os << "__pack_bfloat162(" << value;
1290	    } else {
1291	      os << "," << value << ")";
1292	      if (i != t.lanes() - 1) {
1293	        os << ",";
1294	      } else {
1295	        os << ")";
1296	      }
1297	    }
1298	    return;
1299	  }
1300	
1301	  if (i == 0) {
1302	    os << "make_";
1303	    PrintType(t, os);
1304	    os << "(";
1305	  }
1306	  os << value;
1307	  if (i != t.lanes() - 1) {
1308	    os << ",";
1309	  } else {
1310	    os << ")";
1311	  }
1312	  return;
1313	}
