1315	void CodeGenTileLangHIP::AddFunction(const PrimFunc &f) {
1316	  // clear previous generated state.
1317	  this->InitFuncState(f);
1318	  // reserve keywords
1319	  ReserveKeywordsAsUnique();
1320	
1321	  auto global_symbol = f->GetAttr<String>(tvm::attr::kGlobalSymbol);
1322	  ICHECK(global_symbol.has_value())
1323	      << "CodeGenC: Expect PrimFunc to have the global_symbol attribute";
1324	  bool no_alias = f->HasNonzeroAttr(tir::attr::kNoAlias);
1325	  std::unordered_set<const VarNode *> non_restrict;
1326	  if (auto opt =
1327	          f->GetAttr<ffi::Array<tir::Var>>(tl::attr::kNonRestrictParams)) {
1328	    for (const tir::Var &v : opt.value())
1329	      non_restrict.insert(v.get());
1330	  }
1331	
1332	  this->PrintFuncPrefix(stream);
1333	  CodeGenC::PrintType(f->ret_type, stream);
1334	  this->PrintExtraAttrs(f, stream);
1335	  this->stream << " " << static_cast<std::string>(global_symbol.value()) << "(";
1336	
1337	  for (size_t i = 0; i < f->params.size(); ++i) {
1338	    tir::Var v = f->params[i];
1339	    std::string vid = AllocVarID(v.get());
1340	    if (i != 0)
1341	      stream << ", ";
1342	    if (v.dtype().is_handle()) {
1343	      // work around for grid constant parameters.
1344	      if (auto *ptr = v->type_annotation.as<PointerTypeNode>()) {
1345	        if (ptr->storage_scope == "grid_constant") {
1346	          stream << "__grid_constant__ const ";
1347	          CodeGenC::PrintType(ptr->element_type, stream);
1348	          stream << ' ' << vid;
1349	          continue;
1350	        }
1351	      }
1352	
1353	      auto it = alloc_storage_scope_.find(v.get());
1354	      if (it != alloc_storage_scope_.end()) {
1355	        PrintStorageScope(it->second, stream);
1356	      }
1357	
1358	      CodeGenC::PrintType(GetType(v), stream);
1359	      if (auto *ptr = v->type_annotation.as<PointerTypeNode>()) {
1360	        if (auto *prim = ptr->element_type.as<PrimTypeNode>()) {
1361	          RegisterHandleType(v.get(), prim->dtype);
1362	        }
1363	      }
1364	
1365	      if (no_alias && !non_restrict.count(v.get())) {
1366	        PrintRestrict(v, stream);
1367	      }
1368	    } else {
1369	      CodeGenC::PrintType(GetType(v), stream);
1370	    }
1371	    stream << ' ' << vid;
1372	  }
1373	  stream << ") {\n";
1374	  this->PreFunctionBody(f);
1375	  int func_scope = this->BeginScope();
1376	  this->PrintStmt(f->body);
1377	  this->EndScope(func_scope);
1378	  this->PrintIndent();
1379	  this->stream << "}\n\n";
1380	}
1381	
1382	} // namespace codegen
