28	struct CUDAMath {
29	  std::string operator()(DataType t, std::string name) const {
30	    if (t.is_float()) {
31	      switch (t.bits()) {
32	      case 64:
33	        return name;
34	      case 32:
35	        return name + 'f';
36	      case 16: {
37	        if (name == "fabs") {
38	          return "__habs";
39	        } else if (name == "round") {
40	          return "hrint";
41	        } else {
42	          return "h" + name;
43	        }
44	      }
45	      default:
46	        return "";
47	      }
48	    } else if (t.is_bfloat16()) {
49	      if (name == "fabs") {
50	        return "__habs";
51	      } else if (name == "round") {
52	        return "hrint";
53	      } else {
54	        return "h" + name;
55	      }
56	    } else if (t.is_int() || t.is_uint()) {
57	      switch (t.bits()) {
58	      case 32:
59	        return "__" + name;
60	      case 64:
61	        return "__" + name + "ll";
62	      default:
63	        return "";
64	      }
65	    }
66	    return "";
67	  }
68	};
