113	static std::string GetTileLangFP8Type(DataType type) {
114	  std::stringstream stream;
115	  int32_t lanes = type.lanes();
116	  std::string vec;
117	  if (type.is_scalar()) {
118	    vec = "";
119	  } else if (lanes == 2) {
120	    vec = "_2";
121	  } else if (lanes == 4) {
122	    vec = "_4";
123	  } else if (lanes == 8) {
124	    vec = "_8";
125	  } else if (lanes == 16) {
126	    vec = "_16";
127	  } else if (lanes == 32) {
128	    vec = "_32";
129	  } else {
130	    LOG(FATAL)
131	        << "Only support scalar and vector types of width (2, 4, 8, 16, 32) "
132	           "for FP8";
133	  }
134	  if (type.is_float8_e4m3() || type.is_float8_e4m3fn()) {
135	    stream << "fp8_e4" << vec << "_t";
136	  } else if (type.is_float8_e5m2()) {
137	    stream << "fp8_e5" << vec << "_t";
138	  } else if (type.is_float8_e8m0fnu()) {
139	    stream << "fp8_e8" << vec << "_t";
140	  } else {
141	    LOG(FATAL) << "Unsupported FP8 type in CUDA codegen but got " << type;
142	  }
143	  return stream.str();
144	}
