224	class LaunchConfigExtractor : public tir::StmtVisitor {
225	private:
226	  void VisitStmt_(const AttrStmtNode *op) final {
227	    if (op->attr_key == tir::attr::thread_extent) {
228	      IterVar iv = Downcast<IterVar>(op->node);
229	      if (iv->var->name_hint == "threadIdx.x" ||
230	          iv->thread_tag == "threadIdx.x") {
231	        threadIdx_x_ext = op->value;
232	      } else if (iv->var->name_hint == "threadIdx.y" ||
233	                 iv->thread_tag == "threadIdx.y") {
234	        threadIdx_y_ext = op->value;
235	      } else if (iv->var->name_hint == "threadIdx.z" ||
236	                 iv->thread_tag == "threadIdx.z") {
237	        threadIdx_z_ext = op->value;
238	      }
239	    }
240	    StmtVisitor::VisitStmt_(op);
241	  }
242	
243	public:
244	  PrimExpr threadIdx_x_ext = Integer(1);
245	  PrimExpr threadIdx_y_ext = Integer(1);
246	  PrimExpr threadIdx_z_ext = Integer(1);
247	};
