249	void CodeGenTileLangCUDA::PrintExtraAttrs(const PrimFunc &f) {
250	  LaunchConfigExtractor extractor;
251	  extractor(f->body);
252	  arith::Analyzer analyzer;
253	  PrimExpr threadIdx_ext =
254	      analyzer.Simplify(extractor.threadIdx_x_ext * extractor.threadIdx_y_ext *
255	                        extractor.threadIdx_z_ext);
256	  if (const IntImmNode *const threadIdx_ext_int =
257	          threadIdx_ext.as<IntImmNode>()) {
258	    if (threadIdx_ext_int->value == 1) {
259	      // unable to extract the number of threads per block, hence directly
260	      // return
261	      return;
262	    }
263	    stream << " __launch_bounds__(" << threadIdx_ext_int->value << ", 1)";
264	  }
265	}
