345	void CodeGenTileLangCUDA::VisitStmt_(const tir::ForNode *op) {
346	  if (op->kind == tir::ForKind::kUnrolled) {
347	    PrintIndent();
348	    if (unroll_factor.count(op->loop_var.get())) {
349	      stream << "#pragma unroll "
350	             << PrintExpr(unroll_factor[op->loop_var.get()]) << "\n";
351	    } else {
352	      stream << "#pragma unroll\n";
353	    }
354	  }
355	  std::string extent =
356	      PrintExpr(arith::Analyzer().Simplify(op->extent + op->min));
357	  PrintIndent();
358	  std::string vid = AllocVarID(op->loop_var.get());
359	  std::string start = PrintExpr(op->min);
360	  stream << "for (";
361	  PrintType(op->loop_var.dtype(), stream);
362	  stream << ' ' << vid << " = " << start << "; " << vid << " < " << extent
363	         << "; ++" << vid << ") {\n";
364	  int for_scope = BeginScope();
365	  PrintStmt(op->body);
366	  this->EndScope(for_scope);
367	  PrintIndent();
368	  stream << "}\n";
369	}
