377	void CodeGenTileLangCUDA::PrintType(DataType t, std::ostream &os) { // NOLINT(*)
378	  int lanes = t.lanes();
379	  if (t.is_handle()) {
380	    ICHECK(t.is_scalar()) << "do not yet support vector types";
381	    os << "void*";
382	    return;
383	  }
384	
385	  if (t.is_void()) {
386	    os << "void";
387	    return;
388	  }
389	
390	  if (t == tl::cuTensorMapType()) {
391	    os << "CUtensorMap";
392	    return;
393	  }
394	
395	  bool fail = false;
396	  if (t.is_float()) {
397	    switch (t.bits()) {
398	    case 16:
399	      enable_fp16_ = true;
400	      if (t.is_scalar()) {
401	        os << "half_t";
402	      } else if (lanes <= 8) {
403	        // Emit CUDA code to access fp16 vector elements.
404	        //
405	        // half4 is stored as uint2
406	        //
407	        // h4.x is emitted as *(half2*)(&(u2.x)).x
408	        // h4.y is emitted as *(half2*)(&(u2.x)).y
409	        // h4.z is emitted as *(half2*)(&(u2.y)).x
410	        // h4.w is emitted as *(half2*)(&(u2.y)).y
411	        //
412	        ICHECK_EQ(lanes % 2, 0) << "only support even lane for half type";
413	        os << "uint" << lanes / 2;
414	      } else if (lanes <= 16) {
415	        ICHECK_EQ(lanes % 4, 0) << "only support (mod 4 = 0) lanes for half "
416	                                   "type of more than 8 lanes";
417	        os << "ulonglong" << lanes / 4;
418	      } else {
419	        fail = true;
420	      }
421	      break;
422	    case 32:
423	      if (lanes <= 4) {
424	        os << "float";
425	      } else if (lanes <= 8) {
426	        // Emit CUDA code to access fp32 vector elements for 4 < lanes <= 8.
427	        //
428	        // float8 is stored as ulonglong4
429	        //
430	        // f8.v1 is emitted as *(float2*)(&(ul4.x)).x
431	        // f8.v2 is emitted as *(float2*)(&(ul4.x)).y
432	        //
433	        ICHECK_EQ(lanes % 2, 0)
434	            << "only support even lane for float type with lanes > 4";
435	        os << "ulonglong" << lanes / 2;
436	      } else {
437	        fail = true;
438	      }
439	      break;
440	    case 64:
441	      os << "double";
442	      break;
443	    default:
444	      fail = true;
445	      break;
446	    }
447	    if (!fail && (t.is_scalar() || t.bits() == 16))
448	      return;
449	    if (!fail && (lanes > 4 && lanes <= 8 && t.bits() == 32))
450	      return;
451	    if (!fail && (lanes >= 2 && lanes <= 4)) {
452	      os << lanes;
453	      return;
454	    }
455	  } else if (t.is_bfloat16()) {
456	    enable_bf16_ = true;
457	    if (t.is_scalar()) {
458	      os << "bfloat16_t";
459	    } else if (lanes <= 8) {
460	      ICHECK_EQ(lanes % 2, 0) << "only support even lane for half type";
461	      os << "uint" << lanes / 2;
462	    } else if (lanes <= 16) {
463	      ICHECK_EQ(lanes % 4, 0) << "only support (mod 4 = 0) lanes for half type "
464	                                 "of more than 8 lanes";
465	      os << "ulonglong" << lanes / 4;
466	    } else {
467	      fail = true;
468	    }
469	    if (!fail)
470	      return;
471	  } else if (t.is_float8()) {
472	    enable_fp8_ = true;
473	    os << GetTileLangFP8Type(t);
474	    return;
475	  } else if (t.is_float6()) {
476	    enable_fp6_ = true;
477	    if (t.lanes() <= 4) {
478	      os << GetTileLangFP6Type(t);
479	    }
480	    return;
481	  } else if (t.is_float4()) {
482	    enable_fp4_ = true;
483	    if (t.lanes() <= 64) {
484	      os << GetTileLangFP4Type(t);
485	    } else {
486	      fail = true;
487	    }
488	    return;
489	  } else if (t == DataType::Bool()) {
490	    os << "bool";
491	    return;
492	  } else if (t.is_vector_bool()) {
493	    // CUDA does not support bool vectors.
494	    // Use ushort vectors to represent instead.
495	    int n = t.lanes();
496	    if (n <= 4) {
497	      os << "ushort" << n;
498	      return;
499	    }
500	  } else if (t.is_uint() || t.is_int()) {
501	    if (t.is_uint()) {
502	      os << "u";
503	    }
504	    switch (t.bits()) {
505	    case 1: {
506	      if (t.is_scalar()) {
507	        os << "int";
508	        return;
509	      } else if (t.lanes() == 8) {
510	        os << "int8_t";
511	        return;
512	      } else if (t.lanes() == 16) {
513	        os << "int16_t";
514	        return;
515	      } else if (t.lanes() == 32) {
516	        os << "int";
517	        return;
518	      } else {
519	        LOG(FATAL) << "Cannot convert type " << t << " to CUDA type!";
520	      }
521	    }
522	    case 4: {
523	      if (t.is_scalar()) {
524	        os << "int";
525	        return;
526	      } else if (t.lanes() == 4) {
527	        os << "int16_t";
528	        return;
529	      } else if (t.lanes() == 8) {
530	        // directly 8 4-bit int in integer.
531	        os << "int";
532	        return;
533	      } else if (t.lanes() == 16) {
534	        os << "int2";
535	        return;
536	      } else if (t.lanes() == 32) {
537	        os << "int4";
538	        return;
539	      } else if (t.lanes() == 64) {
540	        os << "int8";
541	        return;
542	      } else {
543	        LOG(FATAL) << "Cannot convert type " << t << " to CUDA type!";
544	      }
545	    }
546	    case 8: {
547	      if (t.lanes() == 4) {
548	        // directly 4 8 bit int in integer.
549	        enable_int8_ = true;
550	
551	        // We use int for int8x4 instead of char4 because using char4 is
552	        // likely to produce extra instructions to pack four int8 elements
553	        // into 32-bit data.
554	        os << "int";
555	        return;
556	      } else if (t.lanes() == 8) {
557	        enable_int8_ = true;
558	        os << "int2";
559	        return;
560	      } else if (t.lanes() == 16) {
561	        enable_int8_ = true;
562	        os << "int4";
563	        return;
564	      } else if (t.lanes() == 32) {
565	        enable_int8_ = true;
566	        os << "longlong4";
567	        return;
568	      } else if (!t.is_uint() && t.is_scalar()) {
569	        os << "signed char";
570	        break;
571	      } else {
572	        os << "char";
573	        break;
574	      }
575	    }
576	    case 16: {
577	      if (t.is_scalar()) {
578	        os << "short";
579	      } else if (t.lanes() <= 4) {
580	        os << "short" << lanes;
581	      } else if (t.lanes() <= 8) {
582	        // Emit CUDA code to access int16 vector elements.
583	        //
584	        // short4 is stored as int2
585	        //
586	        // s4.x is emitted as *(short2*)(&(i2.x)).x
587	        // s4.y is emitted as *(short2*)(&(i2.x)).y
588	        // s4.z is emitted as *(short2*)(&(i2.y)).x
589	        // s4.w is emitted as *(short2*)(&(i2.y)).y
590	        //
591	        ICHECK_EQ(t.lanes() % 2, 0)
592	            << "only support even lane for shorT type with lanes > 4";
593	        os << "int" << t.lanes() / 2;
594	      } else {
595	        fail = true;
596	      }
597	      if (!fail) {
598	        return;
599	      }
600	      break;
601	    }
602	    case 32: {
603	      if (t.is_scalar()) {
604	        os << "int";
605	      } else if (t.lanes() <= 4) {
606	        os << "int" << t.lanes();
607	      } else if (t.lanes() <= 8) {
608	        // Emit CUDA code to access int32 vector elements for 4 < lanes <= 8.
609	        //
610	        // int8 is stored as longlong4
611	        //
612	        // i8.v1 is emitted as *(int2*)(&(l4.x)).x
613	        // i8.v2 is emitted as *(int2*)(&(l4.x)).y
614	        //
615	        ICHECK_EQ(lanes % 2, 0)
616	            << "only support even lane for int32 type with lanes > 4";
617	        os << "longlong" << lanes / 2;
618	      } else {
619	        fail = true;
620	      }
621	      if (!fail) {
622	        return;
623	      }
624	      break;
625	    }
626	    case 64: {
627	      if (t.is_scalar()) {
628	        os << "int64_t";
629	      } else if (t.lanes() == 2) {
630	        os << "longlong2";
631	      } else if (t.lanes() == 3) {
632	        os << "longlong3";
633	      } else if (t.lanes() == 4) {
634	        os << "longlong4";
635	      } else {
636	        fail = true;
637	      }
638	      if (!fail) {
639	        return;
640	      }
641	      break;
642	    }
643	    default:
644	      fail = true;
645	      break;
646	    }
647	    if (!fail && lanes == 1) {
648	      return;
649	    }
650	    if (!fail && (lanes >= 2 && lanes <= 4)) {
651	      os << lanes;
652	      return;
653	    }
654	  }
655	  LOG(FATAL) << "Cannot convert type " << t << " to CUDA type";
656	}
