658	void CodeGenTileLangCUDA::PrintVecBinaryOp(const std::string &op, DataType t,
659	                                           PrimExpr lhs, PrimExpr rhs,
660	                                           std::ostream &os) { // NOLINT(*)
661	  // Declare the result.
662	  std::string sret = name_supply_->FreshName("_");
663	  this->PrintIndent();
664	  this->PrintType(t, stream);
665	  stream << ' ' << sret << ";\n";
666	  int ssa_scope = BeginScope();
667	  {
668	    // Unpack into individual ops.
669	    std::string vlhs = SSAGetID(PrintExpr(lhs), lhs.dtype());
670	    std::string vrhs = SSAGetID(PrintExpr(rhs), rhs.dtype());
671	
672	    for (int i = 0, lanes = t.lanes(); i < lanes; ++i) {
673	      std::ostringstream value_temp;
674	      if (isalpha(op[0])) {
675	        value_temp << op << "(";
676	        PrintVecElemLoad(vlhs, lhs.dtype(), i, value_temp);
677	        value_temp << ", ";
678	        PrintVecElemLoad(vrhs, rhs.dtype(), i, value_temp);
679	        value_temp << ")";
680	      } else {
681	        value_temp << "(";
682	        PrintVecElemLoad(vlhs, lhs.dtype(), i, value_temp);
683	        value_temp << op;
684	        PrintVecElemLoad(vrhs, rhs.dtype(), i, value_temp);
685	        value_temp << ")";
686	      }
687	      PrintVecElemStore(sret, t, i, value_temp.str());
688	    }
689	  }
690	  EndScope(ssa_scope);
691	  os << sret;
692	}
