694	void CodeGenTileLangCUDA::PrintVecElemLoad(const std::string &vec, DataType t,
695	                                           int i,
696	                                           std::ostream &os) { // NOLINT(*)
697	  if (t.is_scalar()) {
698	    os << vec;
699	    return;
700	  }
701	
702	  static const char access[] = {'x', 'y', 'z', 'w'};
703	  ICHECK(i >= 0 && i < 256 / t.bits())
704	      << "i: " << i << " t: " << t << " t.bits(): " << t.bits()
705	      << " t.lanes(): " << t.lanes();
706	  if (t.bits() == 8 && (t.is_int() || t.is_uint())) {
707	    std::string type_name = t.is_int() ? "char" : "unsigned char";
708	    if (t.lanes() == 2 || t.lanes() == 3) {
709	      os << vec << "." << access[i % t.lanes()];
710	    } else if (t.lanes() <= 16) {
711	      std::string ac = t.lanes() == 4 ? vec : (vec + "." + access[i / 4]);
712	      os << "((" << type_name << ")(" << ac << " >> " << i % 4 * 8 << "))";
713	    } else {
714	      ICHECK(t.lanes() == 32);
715	      std::string ac = vec + "." + access[i / 8];
716	      os << "((" << type_name << ")(" << ac << " >> " << i % 8 * 8 << "))";
717	    }
718	  } else if (t.is_float16()) {
719	    if (t.lanes() <= 8) {
720	      os << "((half2*)(&(" << vec << "." << access[i / 2] << ")))->"
721	         << access[i % 2];
722	    } else {
723	      os << "(((half2*)(&(" << vec << "." << access[i / 4] << "))) + "
724	         << (i / 2 % 2) << ")->" << access[i % 2];
725	    }
726	  } else if (t.is_bfloat16()) {
727	    if (t.lanes() <= 8) {
728	      os << "((nv_bfloat162*)(&(" << vec << "." << access[i / 2] << ")))->"
729	         << access[i % 2];
730	    } else {
731	      os << "(((nv_bfloat162*)(&(" << vec << "." << access[i / 4] << "))) + "
732	         << (i / 2 % 2) << ")->" << access[i % 2];
733	    }
734	  } else if (t.is_float8()) {
735	    os << vec;
736	    // fp8_e5_32_t
737	    if (t.lanes() >= 32)
738	      os << "." << access[i / 16];
739	    // fp8_e5_16_t
740	    if (t.lanes() >= 16)
741	      os << "." << access[(i % 16) / 8];
742	    // fp8_e5_8_t
743	    if (t.lanes() >= 8)
744	      os << "." << access[(i % 8) / 4];
745	    // fp8_e5_4_t or fp8_e5_2_t
746	    os << "." << access[i % 4];
747	  } else if (t.is_float4_e2m1fn()) {
748	    os << vec;
749	    // fp4_e2_64_t
750	    if (t.lanes() >= 64)
751	      os << "." << access[i / 32];
752	    // fp4_e2_32_t
753	    if (t.lanes() >= 32)
754	      os << "." << access[(i % 32) / 16];
755	    // fp4_e2_16_t
756	    if (t.lanes() >= 16)
757	      os << "." << access[(i % 16) / 8];
758	    // fp4_e2_8_t
759	    if (t.lanes() >= 8)
760	      os << "." << access[(i % 8) / 4];
761	    // fp4_e2_4_t or fp4_e2_2_t
762	    os << "." << access[i % 4];
763	  } else if (t.lanes() > 4 && t.lanes() <= 8) {
764	    std::string type_name;
765	    if (t.bits() == 16) {
766	      if (t.is_int()) {
767	        type_name = "short";
768	      } else if (t.is_uint()) {
769	        type_name = "ushort";
770	      }
771	    } else if (t.bits() == 32) {
772	      if (t.is_int()) {
773	        type_name = "int";
774	      } else if (t.is_uint()) {
775	        type_name = "uint";
776	      } else if (t.is_float()) {
777	        type_name = "float";
778	      }
779	    }
780	    ICHECK(!type_name.empty());
781	    os << "((" << type_name << "2*)(&(" << vec << "." << access[i / 2]
782	       << ")))->" << access[i % 2];
783	  } else {
784	    os << vec << "." << access[i];
785	  }
786	}
