788	void CodeGenTileLangCUDA::PrintVecElemStore(const std::string &vec, DataType t,
789	                                            int i, const std::string &value) {
790	  this->PrintIndent();
791	  static const char access[] = {'x', 'y', 'z', 'w'};
792	  ICHECK(i >= 0 && i < 256 / t.bits());
793	  if (t.bits() == 8 && (t.is_int() || t.is_uint())) {
794	    if (t.lanes() == 2 || t.lanes() == 3) {
795	      stream << vec << '.' << access[i % t.lanes()] << "="
796	             << "(" << value << ");\n";
797	    } else if (t.lanes() <= 16) {
798	      std::string ac = t.lanes() == 4 ? vec : (vec + "." + access[i / 4]);
799	      stream << ac << "=";
800	      // Do not read the first undef lane.
801	      if (i != 0) {
802	        stream << ac << " & ~(0x000000ff << " << i % 4 * 8 << ") |";
803	      }
804	      stream << "(" << value << " << " << i % 4 * 8 << ");\n";
805	    } else {
806	      ICHECK(t.lanes() == 32);
807	      std::string ac = vec + "." + access[i / 8];
808	      stream << ac << "=";
809	      // Do not read the first undef lane.
810	      if (i != 0) {
811	        stream << ac << " & ~(0x000000ff << " << i % 8 * 8 << ") |";
812	      }
813	      stream << "(" << value << " << " << i % 8 * 8 << ");\n";
814	    }
815	  } else if (t.is_float16()) {
816	    if (t.lanes() <= 8) {
817	      stream << "((half2*)(&(" << vec << "." << access[i / 2] << ")))->"
818	             << access[i % 2] << " = " << value << ";\n";
819	    } else {
820	      stream << "(((half2*)(&(" << vec << "." << access[i / 4] << "))) + "
821	             << (i / 2 % 2) << ")->" << access[i % 2] << " = " << value
822	             << ";\n";
823	    }
824	  } else if (t.is_bfloat16()) {
825	    if (t.lanes() <= 8) {
826	      stream << "((nv_bfloat162*)(&(" << vec << "." << access[i / 2] << ")))->"
827	             << access[i % 2] << " = " << value << ";\n";
828	    } else {
829	      stream << "(((nv_bfloat162*)(&(" << vec << "." << access[i / 4]
830	             << "))) + " << (i / 2 % 2) << ")->" << access[i % 2] << " = "
831	             << value << ";\n";
832	    }
833	  } else if (t.is_float8()) {
834	    stream << vec;
835	    // fp8_e5_32_t
836	    if (t.lanes() >= 32)
837	      stream << "." << access[i / 16];
838	    // fp8_e5_16_t
839	    if (t.lanes() >= 16)
840	      stream << "." << access[(i % 16) / 8];
841	    // fp8_e5_8_t
842	    if (t.lanes() >= 8)
843	      stream << "." << access[(i % 8) / 4];
844	    // fp8_e5_4_t or fp8_e5_2_t
845	    stream << "." << access[i % 4] << " = " << value << ";\n";
846	  } else if (t.lanes() > 4 && t.lanes() <= 8) {
847	    std::string type_name;
848	    if (t.bits() == 16) {
849	      if (t.is_int()) {
850	        type_name = "short";
851	      } else if (t.is_uint()) {
852	        type_name = "ushort";
853	      }
854	    } else if (t.bits() == 32) {
855	      if (t.is_int()) {
856	        type_name = "int";
857	      } else if (t.is_uint()) {
858	        type_name = "uint";
859	      } else if (t.is_float()) {
860	        type_name = "float";
861	      }
862	    }
863	    ICHECK(!type_name.empty());
864	    stream << "((" << type_name << "2*)(&(" << vec << "." << access[i / 2]
865	           << ")))->" << access[i % 2] << " = " << value << ";\n";
866	  } else if (t.is_float4_e2m1fn()) {
867	    stream << vec;
868	    // fp4_e2_64_t
869	    if (t.lanes() >= 64)
870	      stream << "." << access[i / 32];
871	    // fp4_e2_32_t
872	    if (t.lanes() >= 32)
873	      stream << "." << access[(i % 32) / 16];
874	    // fp4_e2_16_t
875	    if (t.lanes() >= 16)
876	      stream << "." << access[(i % 16) / 8];
877	    // fp4_e2_8_t
878	    if (t.lanes() >= 8)
879	      stream << "." << access[(i % 8) / 4];
880	    // fp4_e2_4_t or fp4_e2_2_t
881	    stream << "." << access[i % 4] << " = " << value << ";\n";
882	  } else {
883	    stream << vec << "." << access[i] << " = " << value << ";\n";
884	  }
885	}
