887	void CodeGenTileLangCUDA::PrintStorageSync(const CallNode *op) {
888	  auto args = op->args;
889	  const std::string &sync = args[0].as<StringImmNode>()->value;
890	  if (sync == "warp") {
891	    // DO nothing.
892	  } else if (sync == "shared" || sync == "shared.dyn") {
893	    this->PrintIndent();
894	    if (args.size() == 1) {
895	      this->stream << "__syncthreads();\n";
896	    } else if (args.size() == 2) {
897	      // In contrast to TileLang, here we support runtime determined barrier_id.
898	      std::string barrier_id = PrintExpr(args[1]);
899	      this->stream << "tl::__sync_thread_partial(" << barrier_id << ");\n";
900	    } else if (args.size() == 3) {
901	      // Support runtime determined barrier_id and thread_count.
902	      std::string barrier_id = PrintExpr(args[1]);
903	      std::string thread_count = PrintExpr(args[2]);
904	      this->stream << "tl::__sync_thread_partial(" << barrier_id << ", "
905	                   << thread_count << ");\n";
906	    } else {
907	      LOG(FATAL) << "Invalid number of arguments for storage sync: "
908	                 << args.size();
909	    }
910	  } else if (sync == "global") {
911	    if (!need_global_barrier_) {
912	      need_global_barrier_ = true;
913	    }
914	    // global synchronizer
915	    std::string is_load = PrintExpr(op->args[1]);
916	    std::string num_blocks = PrintExpr(op->args[2]);
917	    this->PrintIndent();
918	    // In theory only threadfence is needed
919	    // but we observed problems with only threadfence
920	    this->stream << "__threadfence_system();\n";
921	    this->PrintIndent();
922	    this->stream << "if (" << is_load << ") {\n";
923	    int wb = this->BeginScope();
924	    this->PrintIndent();
925	    this->stream << "atomicAdd(&" << vid_global_barrier_state_ << ", 1);\n";
926	    this->PrintIndent();
927	    std::string ptr = name_supply_->FreshName("pf");
928	    this->stream << "volatile unsigned* " << ptr << " = &"
929	                 << vid_global_barrier_state_ << ";\n";
930	    this->PrintIndent();
931	    this->stream << vid_global_barrier_expect_ << " += " << num_blocks << ";\n";
932	    this->PrintIndent();
933	    this->stream << "while (" << ptr << "[0] < " << vid_global_barrier_expect_
934	                 << ");\n";
935	    this->EndScope(wb);
936	    this->PrintIndent();
937	    this->stream << "}\n";
938	    this->PrintIndent();
939	    this->stream << "__syncthreads();\n";
940	  }
941	}
