943	void CodeGenTileLangCUDA::PrintStorageScope(const std::string &scope,
944	                                            std::ostream &os) { // NOLINT(*)
945	  ICHECK_NE(scope, "global")
946	      << "Cannot allocate global memory when targeting CUDA. You must pass "
947	         "all global arrays as input instead";
948	  if (scope == "shared" || scope == "shared.barrier") {
949	    os << "__shared__ ";
950	  } else if (scope == "shared.dyn") {
951	    os << "extern __shared__ __align__(1024) ";
952	  }
