955	std::string CodeGenTileLangCUDA::CastFromTo(std::string value, DataType from,
956	                                            DataType target) {
957	  if (from == target)
958	    return value;
959	  std::ostringstream os;
960	  os << "((";
961	  this->PrintType(target, os);
962	  os << ")";
963	  if (from.is_float16() && (target.is_int() || target.is_uint()) &&
964	      target.bits() == 8) {
965	    os << "(";
966	    if (target.is_uint()) {
967	      os << "u";
968	    }
969	    os << "int)";
970	  }
971	  if ((from.is_float16() || from.is_bfloat16()) && target.is_float8()) {
972	    os << "(float)";
973	  }
974	  os << value << ")";
975	  return os.str();
976	}
977	
978	void CodeGenTileLangCUDA::VisitExpr_(const CastNode *op, std::ostream &os) {
979	  DataType from_ty = op->value.dtype();
980	  DataType target_ty = op->dtype;
981	  ICHECK_EQ(target_ty.lanes(), from_ty.lanes());
982	
983	  // Emit simple C-style type conversion.
984	  if (from_ty.is_scalar())
985	    return CodeGenC::VisitExpr_(op, os);
986	
987	  // We could emit make_float4 like calls, but the emitted code looks
988	  // too compact to read. Emit this as vectorized unary ops.
989	  std::string sret = name_supply_->FreshName("_");
990	  this->PrintIndent();
991	  this->PrintType(target_ty, stream);
992	  stream << ' ' << sret << ";\n";
993	  std::string src = SSAGetID(PrintExpr(op->value), from_ty);
994	
995	  int lanes = from_ty.lanes();
996	
997	  auto PrintVectorizedCast =
998	      [&](const std::string &cast_func, const std::string &src_type,
999	          const std::string &dst_type, const std::string &extra_args = "",
1000	          bool src_needs_reinterpret = false,
1001	          bool dst_needs_reinterpret = false) {
1002	        int num_chunks = lanes / 2;
1003	        std::string src_cast = src_needs_reinterpret
1004	                                   ? "reinterpret_cast<" + src_type + "*>"
1005	                                   : "(" + src_type + "*)";
1006	        std::string dst_cast = dst_needs_reinterpret
1007	                                   ? "reinterpret_cast<" + dst_type + "*>"
1008	                                   : "(" + dst_type + "*)";
1009	
1010	        for (int i = 0; i < num_chunks; i++) {
1011	          PrintIndent();
1012	          stream << "(" << dst_cast << "(&" << sret << "))[" << i
1013	                 << "] = " << cast_func << "((" << src_cast << "(&" << src
1014	                 << "))[" << i << "]" << extra_args << ");\n";
1015	        }
1016	        os << sret;
1017	      };
1018	
1019	  // Handle conversion from float16 to float32
1020	  if (from_ty.is_float16() && target_ty.is_float() && target_ty.bits() == 32) {
1021	    // Use __half22float2 for vectorized conversion (half2 -> float2)
1022	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1023	      PrintVectorizedCast("__half22float2", "half2", "float2");
1024	      return;
1025	    }
1026	  }
1027	
1028	  // Handle conversion from float32 to float16
1029	  if (from_ty.is_float() && from_ty.bits() == 32 && target_ty.is_float16()) {
1030	    // Use __float22half2_rn for vectorized conversion (float2 -> half2)
1031	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1032	      PrintVectorizedCast("__float22half2_rn", "float2", "half2");
1033	      return;
1034	    }
1035	  }
1036	
1037	  // Handle conversion from bfloat16 to float32
1038	  if (from_ty.is_bfloat16() && target_ty.is_float() && target_ty.bits() == 32) {
1039	    // Use __bfloat1622float2 for vectorized conversion (bfloat162 -> float2)
1040	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1041	      PrintVectorizedCast("__bfloat1622float2", "__nv_bfloat162", "float2", "",
1042	                          true, false);
1043	      return;
1044	    }
1045	  }
1046	
1047	  // Handle conversion from float32 to bfloat16
1048	  if (from_ty.is_float() && from_ty.bits() == 32 && target_ty.is_bfloat16()) {
1049	    // Use __float22bfloat162_rn for vectorized conversion (float2 -> bfloat162)
1050	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1051	      PrintVectorizedCast("__float22bfloat162_rn", "float2", "__nv_bfloat162",
1052	                          "", false, true);
1053	      return;
1054	    }
1055	  }
1056	
1057	  // Handle conversion from float32 to float8 (E4M3/E5M2)
1058	  if (from_ty.is_float() && from_ty.bits() == 32 &&
1059	      tl::IsCudaVectorizableFP8(target_ty)) {
1060	    bool target_type_is_e4m3 =
1061	        target_ty.is_float8_e4m3() || target_ty.is_float8_e4m3fn();
1062	    std::string type_suffix = target_type_is_e4m3 ? "__NV_E4M3" : "__NV_E5M2";
1063	
1064	    // Use __nv_cvt_float2_to_fp8x2 for vectorized conversion (float2 -> fp8x2)
1065	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1066	      std::string extra_args = ", __NV_SATFINITE, " + type_suffix;
1067	      PrintVectorizedCast("__nv_cvt_float2_to_fp8x2", "float2",
1068	                          "__nv_fp8x2_storage_t", extra_args, false, true);
1069	      return;
1070	    }
1071	  }
1072	
1073	  // Handle conversion from float8 (E4M3/E5M2) to float32
1074	  if (tl::IsCudaVectorizableFP8(from_ty) && target_ty.is_float()) {
1075	    bool from_type_is_e4m3 =
1076	        from_ty.is_float8_e4m3() || from_ty.is_float8_e4m3fn();
1077	    std::string type_suffix = from_type_is_e4m3 ? "__NV_E4M3" : "__NV_E5M2";
1078	
1079	    // Use __tl_cvt_fp8x2_to_float2 for vectorized conversion (fp8x2 -> float2)
1080	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1081	      PrintVectorizedCast("__tl_cvt_fp8x2_to_float2", "__nv_fp8x2_storage_t",
1082	                          "float2", ", " + type_suffix, true, false);
1083	      return;
1084	    }
1085	  }
1086	
1087	  // Handle conversion from float16 to float4 (E2M1)
1088	  if (from_ty.is_float16() && target_ty.is_float4_e2m1fn()) {
1089	    // Use __tl_cvt_half2_to_fp4x2 for vectorized conversion (half2 -> fp4x2)
1090	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1091	      PrintVectorizedCast("__tl_cvt_half2_to_fp4x2", "half2", "uint8_t", "",
1092	                          false, true);
1093	      return;
1094	    }
1095	  }
1096	
1097	  // Handle conversion from float32 to float4 (E2M1)
1098	  if (from_ty.is_float() && target_ty.is_float4_e2m1fn()) {
1099	    // Use __tl_cvt_float2_to_fp4x2 for vectorized conversion (float2 -> fp4x2)
1100	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1101	      PrintVectorizedCast("__tl_cvt_float2_to_fp4x2", "float2", "uint8_t", "",
1102	                          false, true);
1103	      return;
1104	    }
1105	  }
1106	
1107	  // Handle conversion from float4 (E2M1) to float16
1108	  if (from_ty.is_float4_e2m1fn() && target_ty.is_float16()) {
1109	    // Use __tl_cvt_fp4x2_to_half2 for vectorized conversion (fp4x2 -> half2)
1110	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1111	      PrintVectorizedCast("__tl_cvt_fp4x2_to_half2", "uint8_t", "half2", "",
1112	                          true, false);
1113	      return;
1114	    }
1115	  }
1116	
1117	  // Handle conversion from float4 (E2M1) to float32
1118	  if (from_ty.is_float4_e2m1fn() && target_ty.is_float()) {
1119	    // Use __tl_cvt_fp4x2_to_float2 for vectorized conversion (fp4x2 -> float2)
1120	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1121	      PrintVectorizedCast("__tl_cvt_fp4x2_to_float2", "uint8_t", "float2", "",
1122	                          true, false);
1123	      return;
1124	    }
1125	  }
1126	
1127	  // Handle conversion from double to float4 (E2M1)
1128	  if (from_ty.is_float() && from_ty.bits() == 64 &&
1129	      target_ty.is_float4_e2m1fn()) {
1130	    // Use __tl_cvt_double2_to_fp4x2 for vectorized conversion (double2 ->
1131	    // fp4x2)
1132	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1133	      PrintVectorizedCast("__tl_cvt_double2_to_fp4x2", "double2", "uint8_t", "",
1134	                          false, true);
1135	      return;
1136	    }
1137	  }
1138	
1139	  // Handle conversion from float4 (E2M1) to double
1140	  if (from_ty.is_float4_e2m1fn() && target_ty.is_float() &&
1141	      target_ty.bits() == 64) {
1142	    // Use __tl_cvt_fp4x2_to_double2 for vectorized conversion (fp4x2 ->
1143	    // double2)
1144	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1145	      PrintVectorizedCast("__tl_cvt_fp4x2_to_double2", "uint8_t", "double2", "",
1146	                          true, false);
1147	      return;
1148	    }
1149	  }
1150	
1151	  // Handle conversion from bfloat16 to float4 (E2M1)
1152	  if (from_ty.is_bfloat16() && target_ty.is_float4_e2m1fn()) {
1153	    // Use __tl_cvt_bfloat162_to_fp4x2 for vectorized conversion (bfloat162 ->
1154	    // fp4x2)
1155	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1156	      PrintVectorizedCast("__tl_cvt_bfloat162_to_fp4x2", "__nv_bfloat162",
1157	                          "uint8_t", "", false, true);
1158	      return;
1159	    }
1160	  }
1161	
1162	  // Handle conversion from float4 (E2M1) to bfloat16
1163	  if (from_ty.is_float4_e2m1fn() && target_ty.is_bfloat16()) {
1164	    // Use __tl_cvt_fp4x2_to_bfloat162 for vectorized conversion (fp4x2 ->
1165	    // bfloat162)
1166	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1167	      PrintVectorizedCast("__tl_cvt_fp4x2_to_bfloat162", "uint8_t",
1168	                          "__nv_bfloat162", "", true, false);
1169	      return;
1170	    }
1171	  }
1172	
1173	  // Fallback: elementwise cast
1174	  for (int i = 0, lanes = from_ty.lanes(); i < lanes; ++i) {
1175	    std::ostringstream val;
1176	    val << "(";
1177	    PrintType(target_ty.element_of(), val);
1178	    val << ")(";
1179	    PrintVecElemLoad(src, from_ty, i, val);
1180	    val << ")";
1181	    PrintVecElemStore(sret, target_ty, i, val.str());
1182	  }
1183	
1184	  os << sret;
1185	}
