1187	void CodeGenTileLangCUDA::VisitExpr_(const MinNode *op, std::ostream &os) {
1188	  // TODO(wt): Consider vectorized reduction and impl for other dtypes
1189	  DataType t = op->dtype;
1190	
1191	  // Standard min/max functions don't support bfloat16 or float16
1192	  if ((t.is_bfloat16() || t.is_float16()) && t.is_scalar()) {
1193	    os << "cutlass::fast_min(" << PrintExpr(op->a) << ", " << PrintExpr(op->b)
1194	       << ")";
1195	    return;
1196	  }
1197	
1198	  // For float32 and float64 scalar, use standard min functions
1199	  if (t.is_float() && t.is_scalar()) {
1200	    if (t.bits() == 32 || t.bits() == 64) {
1201	      os << "min(" << PrintExpr(op->a) << ", " << PrintExpr(op->b) << ")";
1202	      return;
1203	    }
1204	  }
1205	
1206	  // For all other scalar types (int, uint), use default implementation
1207	  CodeGenC::VisitExpr_(op, os);
1208	}
