1233	void CodeGenTileLangCUDA::PrintCallExtern(Type ret_type, String global_symbol,
1234	                                          const Array<PrimExpr> &args,
1235	                                          bool skip_first_arg,
1236	                                          std::ostream &os) { // NOLINT(*)
1237	  DataType ret_dtype = GetRuntimeDataType(ret_type);
1238	  if (ret_dtype.is_fixed_length_vector()) {
1239	    //
1240	    // Emit an unsupported vector call
1241	    //
1242	    // v = intrin_f((float4*)A[0], (float4*)B[0])
1243	    //
1244	    // as
1245	    //
1246	    // float4 __ret;
1247	    // {
1248	    //   float4 __arg0 = ((float4*)A)[0];
1249	    //   float4 __arg1 = ((float4*)B)[0];
1250	    //   __ret.x = intrin_f(__arg0.x, __arg1.x);
1251	    //   __ret.y = intrin_f(__arg0.y, __arg1.y);
1252	    //   __ret.z = intrin_f(__arg0.z, __arg1.z);
1253	    //   __ret.w = intrin_f(__arg0.w, __arg1.w);
1254	    // }
1255	    // v = __ret;
1256	    //
1257	    // Declare the result vector.
1258	    std::string sret = name_supply_->FreshName("_");
1259	    this->PrintIndent();
1260	    this->PrintType(ret_dtype, stream);
1261	    stream << ' ' << sret << ";\n";
1262	    {
1263	      // Load arguments.
1264	      std::vector<std::string> sargs;
1265	      size_t arg_begin = static_cast<size_t>(skip_first_arg);
1266	      for (size_t i = arg_begin; i < args.size(); ++i) {
1267	        std::string val = SSAGetID(PrintExpr(args[i]), args[i].dtype());
1268	        sargs.push_back(std::move(val));
1269	      }
1270	
1271	      // Emit a scalar call for each lane.
1272	      for (int i = 0; i < ret_dtype.lanes(); ++i) {
1273	        std::ostringstream scall;
1274	        scall << global_symbol << "(";
1275	        for (size_t j = 0; j < sargs.size(); ++j) {
1276	          if (j > 0)
1277	            scall << ", ";
1278	          PrintVecElemLoad(sargs[j], args[arg_begin + j].dtype(), i, scall);
1279	        }
1280	        scall << ")";
1281	        PrintVecElemStore(sret, ret_dtype, i, scall.str());
1282	      }
1283	    }
1284	    os << sret;
1285	  } else {
1286	    CodeGenC::PrintCallExtern(ret_type, global_symbol, args, skip_first_arg,
1287	                              os);
1288	  }
1289	}
