1291	// Print a reference expression to a buffer.
1292	std::string CodeGenTileLangCUDA::GetBufferRef(DataType t,
1293	                                              const BufferNode *buffer,
1294	                                              PrimExpr index) {
1295	  const VarNode *buffer_var = buffer->data.get();
1296	  std::ostringstream os;
1297	  std::string vid = GetVarID(buffer_var);
1298	  std::string scope;
1299	  if (alloc_storage_scope_.count(buffer_var)) {
1300	    scope = alloc_storage_scope_.at(buffer_var);
1301	  }
1302	  // bool is_vol = IsVolatile(buffer_var);
1303	  // always false for tl cutlass backend.
1304	  bool is_vol = false;
1305	
1306	  auto ptr_cast = [this, is_vol, scope](DataType pointed_to) {
1307	    std::ostringstream ptr_os;
1308	    ptr_os << "(";
1309	    if (is_vol) {
1310	      ptr_os << "volatile ";
1311	    }
1312	    if (!scope.empty() && IsScopePartOfType()) {
1313	      PrintStorageScope(scope, ptr_os);
1314	    }
1315	    PrintType(pointed_to, ptr_os);
1316	    ptr_os << "*)";
1317	    return ptr_os.str();
1318	  };
1319	
1320	  DataType buffer_element_dtype = buffer->dtype;
1321	
1322	  std::string buffer_str = vid;
1323	  if (!HandleTypeMatch(buffer_var, buffer_element_dtype) || is_vol) {
1324	    std::stringstream temp;
1325	    temp << "(" << ptr_cast(buffer_element_dtype) << vid << ")";
1326	    buffer_str = temp.str();
1327	  }
1328	  if (scope.empty()) {
1329	    scope = GetPtrStorageScope(buffer->data);
1330	  }
1331	  if (scope == "local.var" || scope.find("local.descriptor") == 0) {
1332	    os << vid;
1333	    return os.str();
1334	  }
1335	  std::string index_str = PrintExpr(index);
1336	  if ((t.bits() == 4 && !t.is_float4()) || (t.bits() == 1 && t.is_int())) {
1337	    // This is a special case, because CodegenCUDA::PrintType()
1338	    // returns "int" for bool and for 4-bit integers. In most cases,
1339	    // we divide by the number of lanes to determine the index.
1340	    // However, the backing type for scalar int4 and scalar bool is
1341	    // int32.  Therefore, we need to divide by the ratio of their
1342	    // sizes in that case.
1343	    int div_factor = (t.lanes() == 1) ? (32 / t.bits()) : t.lanes();
1344	    index_str =
1345	        PrintExpr(arith::Analyzer().Simplify(truncdiv(index, div_factor)));
1346	
1347	    os << "*((" << ptr_cast(t) << vid << ")" << " + " << index_str << ")";
1348	  } else if (t == buffer_element_dtype) {
1349	    os << buffer_str << "[" << index_str << "]";
1350	  } else {
1351	    // Fix fp4 pointer arithmetic: fp4 elements are 4-bit packed 2 per byte.
1352	    // fp4* + n incorrectly advances n bytes (skipping 2n elements).
1353	    int div_factor = 1;
1354	    if (buffer_element_dtype.is_float4() && buffer_element_dtype.lanes() == 1) {
1355	      div_factor = 2;
1356	    }
1357	    index_str =
1358	        PrintExpr(arith::Analyzer().Simplify(truncdiv(index, div_factor)));
1359	
1360	    os << "*" << ptr_cast(t) << "(" << buffer_str << " + " << index_str << ")";
1361	  }
1362	
1363	  return os.str();
1364	}
1365	
1366	std::string CodeGenTileLangCUDA::GetVecLoad(DataType t,
1367	                                            const BufferNode *buffer,
1368	                                            PrimExpr base) {
1369	  const VarNode *buffer_var = buffer->data.get();
1370	  std::string scope;
1371	  if (alloc_storage_scope_.count(buffer_var)) {
1372	    scope = alloc_storage_scope_.at(buffer_var);
1373	  }
1374	  if (scope.empty()) {
1375	    scope = GetPtrStorageScope(buffer->data);
1376	  }
1377	
1378	  if (scope != "global" || t.bits() * t.lanes() <= 128) {
1379	    return this->CodeGenC::GetVecLoad(t, buffer, base);
1380	  }
1381	  ICHECK_EQ(t.bits() * t.lanes(), 256)
1382	      << "Unsupported vector load size: " << t.bits() * t.lanes();
1383	  auto buffer_ref = this->GetBufferRef(t, buffer, base);
1384	  std::ostringstream os;
1385	  os << "tl::ld_global_256(&(" << buffer_ref << "))";
1386	  return os.str();
1387	}
