1389	void CodeGenTileLangCUDA::PrintVecStore(const BufferNode *buffer, DataType t,
1390	                                        PrimExpr base,
1391	                                        const std::string &value) {
1392	  const VarNode *buffer_var = buffer->data.get();
1393	  std::string scope;
1394	  if (alloc_storage_scope_.count(buffer_var)) {
1395	    scope = alloc_storage_scope_.at(buffer_var);
1396	  }
1397	  if (scope.empty()) {
1398	    scope = GetPtrStorageScope(buffer->data);
1399	  }
1400	
1401	  if (scope != "global" || t.bits() * t.lanes() <= 128) {
1402	    this->CodeGenC::PrintVecStore(buffer, t, base, value);
1403	    return;
1404	  }
1405	  ICHECK_EQ(t.bits() * t.lanes(), 256)
1406	      << "Unsupported vector load size: " << t.bits() * t.lanes();
1407	  auto buffer_ref = this->GetBufferRef(t, buffer, base);
1408	  this->PrintIndent();
1409	  this->stream << "tl::st_global_256(&(" << buffer_ref << "), " << value
1410	               << ");\n";
